test("dashboard: one sections view, core cards plus the integration's own picture card", () => {
  const dash = buildDashboard(fixture("full-pool"), { title: "Backyard pool" });
  assert.equal(dash.title, "Backyard pool");
  assert.equal(dash.views.length, 1);
  assert.equal(dash.views[0].type, "sections");
  const types = dash.views[0].sections.flatMap((s) => s.cards.map((c) => c.type));
  for (const t of types) assert.ok(CORE_CARDS.has(t) || t === PICTURE_CARD, t);
  assert.ok(types.includes(PICTURE_CARD));
  const plain = buildDashboard(fixture("full-pool"), { pictures: false });
  for (const t of plain.views[0].sections.flatMap((s) => s.cards.map((c) => c.type))) {
    assert.ok(CORE_CARDS.has(t), t);
  }
});

/* ----- Animated pictures (0.3.0) ----------------------------------------- */

test("pictures: false, controls: core reproduces the v0.2.1 output byte for byte", () => {
  for (const name of SHAPES) {
    const out = JSON.stringify(buildDashboard(fixture(name), { pictures: false, ...CORE }), null, 2) + "\n";
    assert.equal(out, snapshot(name), name);
  }
  // Only the pictures were added: with them stripped, today's core output is v0.2.1's.
  for (const name of SHAPES) {
    const dash = buildDashboard(fixture(name), CORE);
    for (const s of dash.views[0].sections) s.cards = s.cards.filter((c) => c.type !== PICTURE_CARD);
    assert.equal(JSON.stringify(dash, null, 2) + "\n", snapshot(name), name);
  }
});

test("full pool: one overview of the whole pool at the top of the pumps section", () => {
  const hass = fixture("full-pool");
  const pumps = buildSection(hass, "pumps");
  const expected = {
    type: PICTURE_CARD,
    scene: "overview",
    pumps: {
      pool: "fan.backyard_filter_pump",
      spa: "fan.backyard_spa_jets",
      falls: "fan.backyard_waterfall",
    },
    lights: { pool: "light.backyard_pool_light", spa: "light.backyard_spa_light" },
    spillover: "sensor.backyard_filter_pump_current_mode",
    grid_options: { columns: "full" },
  };
  assert.deepEqual(pumps.cards[1], expected);
  assert.equal(pumps.cards[0].type, "heading");
  assert.equal(pumps.cards[2].entity, "fan.backyard_filter_pump", "the pool pump's speed sits right under it");
  assert.equal(buildSection(hass, "pumps", CORE).cards[2].entity, "fan.backyard_cleaner_booster", "core: tiles in name order");
  // No shape or style key unless asked: the card falls back to the module defaults.
  assert.equal("shape" in pumps.cards[1], false);
  assert.equal("style" in pumps.cards[1], false);
  // The cleaner booster and the solar pump move water nobody watches.
  assert.equal(pictures(buildSections(hass)).length, 1);
  // Pictures live in the pumps section only.
  for (const type of EQUIPMENT_TYPES.filter((t) => t !== "pumps")) {
    const section = buildSection(hass, type);
    if (section) assert.equal(pictures([section]).length, 0, type);
  }
});

test("full pool, pictures: features: pool, spa and waterfall pictures instead of the overview", () => {
  const hass = fixture("full-pool");
  const pumps = buildSection(hass, "pumps", FEATURES);
  const expected = [
    {
      type: PICTURE_CARD,
      scene: "pool",
      pump: "fan.backyard_filter_pump",
      light: "light.backyard_pool_light",
      grid_options: { columns: "full" },
    },
    {
      type: PICTURE_CARD,
      scene: "spa",
      pump: "fan.backyard_spa_jets",
      light: "light.backyard_spa_light",
      spillover: "sensor.backyard_filter_pump_current_mode",
      grid_options: { columns: "full" },
    },
    {
      type: PICTURE_CARD,
      scene: "falls",
      pump: "fan.backyard_waterfall",
      grid_options: { columns: "full" },
    },
  ];
  assert.deepEqual(pumps.cards.slice(1, 4), expected);
  assert.equal(pumps.cards[0].type, "heading");
  assert.equal(pumps.cards[4].entity, "fan.backyard_filter_pump", "the pool pump's tile follows its pictures");
  assert.equal(buildSection(hass, "pumps", { ...FEATURES, ...CORE }).cards[4].entity, "fan.backyard_cleaner_booster");
  assert.equal(pictures(buildSections(hass, FEATURES)).length, 3);
  assert.equal(pictures(buildSections(hass, FEATURES)).some((c) => c.scene === "overview"), false);
});

